from collections import deque
H,W=T.shape
out=T.copy()
comp_data={1:[9,7],2:[5,9,7],3:[6,2,5],4:[7,4],5:[7,3,5],6:[5,3]}
for cid,palette in comp_data.items():
    mask=(labels==cid)
    depth=np.full((H,W),-1,dtype=int)
    q=deque()
    for r,c in np.argwhere(mask):
        r=int(r);c=int(c)
        if r==0 or r==H-1 or c==0 or c==W-1 or any(not (0<=r+dr<H and 0<=c+dc<W) or not mask[r+dr,c+dc] for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))):
            depth[r,c]=0;q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and mask[nr,nc] and depth[nr,nc]<0:
                depth[nr,nc]=depth[r,c]+1;q.append((nr,nc))
    for r,c in np.argwhere(mask):
        out[r,c]=palette[int(depth[r,c])%len(palette)]
import json
output_json=json.dumps(out.tolist(),separators=(',',':'))
print(output_json)
